SELECT count(*) AS mrp_batches, count(*) FILTER (WHERE EXISTS (SELECT 1 FROM "FactoryPlanningBatch" f WHERE f."batchCode" = m.name)) AS in_planning, count(*) FILTER (WHERE EXISTS (SELECT 1 FROM "FactoryProductionBatch" f WHERE f."batchCode" = m.name)) AS in_production, count(*) FILTER (WHERE m."dealId" IS NOT NULL) AS with_deal_id, count(DISTINCT m.name) AS distinct_names FROM "MrpManufacturingBatch" m
